import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

const fridaRoot = path.resolve(import.meta.dirname, '..', '..');
const hostDir = path.join(fridaRoot, 'hosts', 'node-cli');

test('node-cli JavaScript entrypoints are generated from TypeScript sources', () => {
  const generatedBanner =
    'Generated from hosts/node-cli/*.ts by scripts/build-hosts.mjs. Do not edit this file directly.';
  const jsFiles = fs
    .readdirSync(hostDir)
    .filter(file => file.endsWith('.js'))
    .sort();

  assert.ok(jsFiles.length > 0, 'expected generated JavaScript entrypoints');

  jsFiles.forEach(jsFile => {
    const tsPeer = jsFile.replace(/\.js$/, '.ts');
    const tsPath = path.join(hostDir, tsPeer);
    const jsPath = path.join(hostDir, jsFile);
    const jsSource = fs.readFileSync(jsPath, 'utf8').replace(/^\uFEFF/, '');

    assert.equal(fs.existsSync(tsPath), true, `missing TypeScript peer for ${jsFile}`);
    assert.equal(
      jsSource.startsWith('#!/usr/bin/env node'),
      true,
      `${jsFile} should keep a node shebang`
    );
    assert.match(jsSource, new RegExp(generatedBanner.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')));
  });
});
